const progressKey="shikshaSaathiProgressV2";
function readLearningProgress(){try{return JSON.parse(localStorage.getItem(progressKey))||{lessons:[],scores:[]}}catch(e){return {lessons:[],scores:[]}}}
function updateLearningProgress(data){localStorage.setItem(progressKey,JSON.stringify(data));renderLearningProgress()}
function localizedItem(topic,index,item){if(currentLanguage==="en")return item;const li=currentLanguage==="hi"?0:1;const prompt=localizedQuizPrompts[topic][index][li];return {...item,q:prompt,options:item.options.map(o=>localizedQuizOptions[o]?.[li]||o)}}
function renderLearningProgress(){
 const box=document.getElementById("completedLessonsCount");if(!box)return;const d=readLearningProgress(),w=translations[currentLanguage]||translations.en;
 box.textContent=d.lessons.length;document.getElementById("quizzesTakenCount").textContent=d.scores.length;
 document.getElementById("averageScore").textContent=d.scores.length?Math.round(d.scores.reduce((a,x)=>a+x.score/x.total*100,0)/d.scores.length)+"%":"—";
 const ll=document.getElementById("completedLessonsList");ll.innerHTML="";if(!d.lessons.length){const li=document.createElement("li");li.textContent=w.noLessons;ll.appendChild(li)}
 d.lessons.slice().reverse().forEach(k=>{const li=document.createElement("li");const subject=k.split(":")[0];const names=(translations[currentLanguage].subjectNames||translations.en.subjectNames);li.textContent=(names[subject]||subject)+" — "+(currentLanguage==="hi"?"पूरा हुआ":currentLanguage==="mr"?"पूर्ण":"Completed");ll.appendChild(li)});
 const sl=document.getElementById("recentScoresList");sl.innerHTML="";if(!d.scores.length){const li=document.createElement("li");li.textContent=w.noScores;sl.appendChild(li)}
 d.scores.slice(-5).reverse().forEach(x=>{const li=document.createElement("li");const topicNames={computer:{en:"Computer Basics",hi:"कंप्यूटर",mr:"संगणक"},science:{en:"Science",hi:"विज्ञान",mr:"विज्ञान"},math:{en:"Mathematics",hi:"गणित",mr:"गणित"},english:{en:"English Grammar",hi:"अंग्रेज़ी व्याकरण",mr:"इंग्रजी व्याकरण"},gk:{en:"General Knowledge",hi:"सामान्य ज्ञान",mr:"सामान्य ज्ञान"}};li.textContent=topicNames[x.topic][currentLanguage]+": "+x.score+"/"+x.total+" ("+Math.round(x.score/x.total*100)+"%)";sl.appendChild(li)});
}
function markLessonComplete(subject){const d=readLearningProgress(),key=subject;if(!d.lessons.includes(key)){d.lessons.push(key);updateLearningProgress(d)}const b=document.getElementById("markLessonCompleteBtn");if(b){b.textContent=translations[currentLanguage].lessonCompleted;b.disabled=true}}
function resetProgress(){if(!confirm(translations[currentLanguage].resetConfirm))return;localStorage.removeItem(progressKey);renderLearningProgress();const b=document.getElementById("markLessonCompleteBtn");if(b){b.disabled=false;b.textContent=translations[currentLanguage].markComplete}}
function quizExplanation(topic,item){
 const a=item.options[item.answer];
 if(currentLanguage==="hi")return topic==="math"?"गणना करने पर सही परिणाम "+a+" मिलता है।":topic==="english"?"अंग्रेज़ी व्याकरण या शब्द के अर्थ के अनुसार "+a+" सही विकल्प है।":topic==="computer"?a+" कंप्यूटर के इस भाग या काम का सही नाम/उपयोग है।":topic==="science"?"विज्ञान के तथ्य के अनुसार "+a+" सही उत्तर है।":"सामान्य ज्ञान के तथ्य के अनुसार सही उत्तर "+a+" है।";
 if(currentLanguage==="mr")return topic==="math"?"गणना केल्यावर योग्य उत्तर "+a+" मिळते.":topic==="english"?"इंग्रजी व्याकरण किंवा शब्दाच्या अर्थानुसार "+a+" योग्य पर्याय आहे.":topic==="computer"?a+" हे संगणकाच्या या भागाचे किंवा कार्याचे योग्य नाव/वापर आहे.":topic==="science"?"वैज्ञानिक माहितीनुसार "+a+" योग्य उत्तर आहे.":"सामान्य ज्ञानानुसार योग्य उत्तर "+a+" आहे.";
 return topic==="math"?"Working through the calculation gives "+a+".":topic==="english"?a+" follows the English grammar rule or word meaning being tested.":topic==="computer"?a+" is the correct name or function of this computer component.":topic==="science"?a+" is the scientific fact that answers this question.":a+" is the established general-knowledge fact asked about here.";
}
function showQuizQuestion(){
 const topic=document.getElementById("quizTopic").value,bank=quizBank[topic]||[],raw=bank[currentQuizQuestion];if(!raw)return;
 const item=localizedItem(topic,currentQuizQuestion,raw),w=translations[currentLanguage]||translations.en,container=document.getElementById("quizQuestions"),result=document.getElementById("result");container.innerHTML="";result.textContent="";result.dataset.status="";
 const pre=currentLanguage==="en"?"Question ":"प्रश्न ",join=currentLanguage==="en"?" of ":" / ";document.getElementById("quizProgress").textContent=pre+(currentQuizQuestion+1)+join+bank.length;
 const card=document.createElement("article");card.className="quiz-question-card";const heading=document.createElement("h3");heading.textContent=(currentQuizQuestion+1)+". "+item.q;card.appendChild(heading);
 item.options.forEach((o,i)=>{const label=document.createElement("label");label.className="quiz-option";const input=document.createElement("input");input.type="radio";input.name="quiz-"+topic+"-"+currentQuizQuestion;input.value=String(i);input.checked=currentQuizAnswers[currentQuizQuestion]===i;input.disabled=document.getElementById("submitQuizBtn").disabled;input.addEventListener("change",()=>{currentQuizAnswers[currentQuizQuestion]=i;result.textContent=""});label.append(input,document.createTextNode(" "+o));card.appendChild(label)});container.appendChild(card);
 document.getElementById("previousQuizBtn").textContent=w.quizPrevious;document.getElementById("nextQuizBtn").textContent=w.quizNext;document.getElementById("submitQuizBtn").textContent=w.quizSubmit;
 document.getElementById("previousQuizBtn").disabled=currentQuizQuestion===0||document.getElementById("submitQuizBtn").disabled;
 document.getElementById("nextQuizBtn").hidden=currentQuizQuestion===bank.length-1||document.getElementById("submitQuizBtn").disabled;
 document.getElementById("submitQuizBtn").hidden=currentQuizQuestion!==bank.length-1||document.getElementById("submitQuizBtn").disabled;
 if(document.getElementById("submitQuizBtn").disabled)renderQuizReview();
}
function renderQuizReview(){
 const topic=document.getElementById("quizTopic").value,bank=quizBank[topic]||[],w=translations[currentLanguage]||translations.en,c=document.getElementById("quizQuestions");c.innerHTML="";
 bank.forEach((raw,i)=>{const item=localizedItem(topic,i,raw),card=document.createElement("article");card.className="quiz-question-card";const h=document.createElement("h3");h.textContent=(i+1)+". "+item.q;const box=document.createElement("div");box.className="quiz-explanation";
 const sel=currentQuizAnswers[i],your=sel===undefined?"—":item.options[sel],correctLabel=w.quizCorrectLabel||"Correct answer",yourLabel=currentLanguage==="hi"?"आपका उत्तर":currentLanguage==="mr"?"तुमचे उत्तर":"Your answer";
 const p1=document.createElement("p");p1.textContent=correctLabel+": "+item.options[raw.answer];const p2=document.createElement("p");p2.textContent=yourLabel+": "+your+" — "+(sel===raw.answer?(currentLanguage==="hi"?"✓ सही":currentLanguage==="mr"?"✓ बरोबर":"✓ Correct"):(currentLanguage==="hi"?"✗ फिर अभ्यास करें":currentLanguage==="mr"?"✗ पुन्हा सराव करा":"✗ Review this"));
 const p3=document.createElement("p");p3.textContent=(w.correctWhy||"Why this is correct")+": "+quizExplanation(topic,item);box.append(p1,p2,p3);card.append(h,box);c.appendChild(card)});
 const retry=document.createElement("button");retry.type="button";retry.className="primary-btn";retry.textContent=w.quizRetry;retry.addEventListener("click",renderQuiz);c.appendChild(retry);
}
function checkQuiz(){
 const topic=document.getElementById("quizTopic").value,bank=quizBank[topic]||[],w=translations[currentLanguage]||translations.en,unanswered=bank.length-Object.keys(currentQuizAnswers).length;
 if(unanswered>0){document.getElementById("result").textContent=(w.quizUnanswered||"Answer all questions before submitting.")+" ("+unanswered+")";return}
 const score=bank.reduce((sum,x,i)=>sum+(currentQuizAnswers[i]===x.answer?1:0),0),result=document.getElementById("result"),praise=score===bank.length?w.quizExcellent:score>=7?w.quizGreat:score>=4?w.quizGood:w.quizKeep;
 result.textContent=(w.quizScore||"Your score")+": "+score+" / "+bank.length+" — "+praise;result.dataset.score=String(score);
 const d=readLearningProgress();d.scores.push({topic,score,total:bank.length,date:new Date().toISOString()});if(d.scores.length>50)d.scores=d.scores.slice(-50);updateLearningProgress(d);
 document.getElementById("submitQuizBtn").disabled=true;document.getElementById("nextQuizBtn").hidden=true;document.getElementById("previousQuizBtn").disabled=true;renderQuizReview();
}

